Uint8List smaaTable(bool area) {
  final encoded = base64Decode(area ? _area : _search);
  final result = Uint8List(area ? 160 * 560 * 4 : 64 * 16 * 4);
  var offset = 0;
  for (var i = 0; i < encoded.length; i += 2) {
    result.fillRange(offset, offset + encoded[i], encoded[i + 1]);
    offset += encoded[i];
  }
  if (offset != result.length) throw StateError('Invalid SMAA table.');
  final rgba = Uint8List(result.length);
  final count = result.length ~/ 4;
  for (var c = 0; c < 4; c++) {
    for (var i = 0; i < count; i++) {
      rgba[i * 4 + c] = result[c * count + i];
    }
  }
  return rgba;
}

